import{_ as e,o as a,c as d,a2 as r}from"./chunks/framework.yo2CxoV2.js";const f=JSON.parse('{"title":"序衡 Ordloom","description":"","frontmatter":{},"headers":[],"relativePath":"README.md","filePath":"README.md","lastUpdated":1794339637000}'),o={name:"README.md"};function l(i,t,h,s,n,m){return a(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="序衡-ordloom" tabindex="-1">序衡 Ordloom <a class="header-anchor" href="#序衡-ordloom" aria-label="Permalink to &quot;序衡 Ordloom&quot;">​</a></h1><p>为 Django 项目提供清晰、统一的业务管理空间。</p><p>Ordloom 基于 React 19 与 Ant Design 6，读取已注册的 <code>ModelAdmin</code>，把模型、权限、表单和业务操作呈现在一个工作台中。后端继续执行 Django 的 queryset、ModelForm、FormSet 和保存钩子。</p><h2 id="可以用它做什么" tabindex="-1">可以用它做什么 <a class="header-anchor" href="#可以用它做什么" aria-label="Permalink to &quot;可以用它做什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>使用的能力</th></tr></thead><tbody><tr><td>项目、客户、订单管理</td><td>搜索、筛选、分页、行内编辑、批量操作</td></tr><tr><td>主从业务录入</td><td>fieldsets、普通/通用关联明细、整体校验与事务保存</td></tr><tr><td>内容与知识库</td><td>富文本、Markdown、图片、文件、JSON</td></tr><tr><td>组织与账号管理</td><td>原生 UserAdmin、项目密码策略、自定义登录字段、权限感知界面</td></tr><tr><td>不同品牌的后台</td><td>主题、明暗模式、站点名称、Logo、密度及工作台布局</td></tr><tr><td>页面公开分享与运维</td><td>分享密码失败限速、超级管理员只读任务运行诊断</td></tr><tr><td>业务数据分析</td><td>模型字段目录、GraphQL 筛选聚合、数据集发布版本、报表与看板</td></tr><tr><td>大屏与移动页面</td><td>拖拽搭建、ECharts/AntV、滚动动画、组件数据绑定与轮播</td></tr><tr><td>问卷与线索收集</td><td>12 类题目、提交校验、答卷快照、CSV/Excel 与汇总</td></tr><tr><td>团队和系统集成</td><td>工作区、组织目录、所有权、通知、Webhook、只读服务与离线快照</td></tr></tbody></table><h2 id="从这里开始" tabindex="-1">从这里开始 <a class="header-anchor" href="#从这里开始" aria-label="Permalink to &quot;从这里开始&quot;">​</a></h2><ol><li><a href="./getting-started/installation.html">安装并接管管理入口</a>。</li><li><a href="./getting-started/quickstart.html">为一个业务模型配置列表和表单</a>。</li><li><a href="./getting-started/example.html">运行可直接体验的完整示例</a>。</li><li><a href="./components/overview.html">浏览 32 种字段组件</a>，再按需要接入编辑器、上传和关联选择。</li><li><a href="./data/graphql.html">开放模型数据</a>，在 <a href="./data/datasets.html">数据集工作室</a> 保存查询并绑定组件。</li><li><a href="./guides/visual-pages.html">搭建大屏与 H5</a>，或使用 <a href="./data/reports.html">报表与看板</a> 分析业务数据。</li><li>按部署需要启用 <a href="./guides/collaboration.html">协作</a>、<a href="./data/events-and-services.html">变更通知与只读服务</a>、<a href="./guides/offline.html">离线</a> 和 <a href="./development/commands.html">维护命令</a>。</li></ol><h2 id="版本与接入" tabindex="-1">版本与接入 <a class="header-anchor" href="#版本与接入" aria-label="Permalink to &quot;版本与接入&quot;">​</a></h2><p>本手册对应 <strong>Ordloom 1.0.0</strong>。发行包和模块为 <code>ordloom</code>，可选数据层为 <code>ordloom[graphql]</code>；表使用 <code>ordloom_*</code>，迁移应用标签和权限前缀为 <code>ordloom</code>，设置为 <code>ORDLOOM_*</code>，管理命令为 <code>ordloom_*</code>。</p><p>完整能力清单、默认开关及部署边界见 <a href="./releases/1.0.0.html">发布说明</a>、<a href="./reference/settings.html">配置参考</a> 和 <a href="./reference/compatibility.html">环境要求</a>。</p>',10)])])}const p=e(o,[["render",l]]);export{f as __pageData,p as default};
